package com.paymesh.backend.security.auth;
import com.paymesh.backend.testing.BusinessJwtTestSupport;
import com.paymesh.backend.chat.*;
import com.paymesh.backend.security.accounts.*;
import com.paymesh.backend.investigation.AiRequestBudget;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import java.util.function.Consumer;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.*;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
@SpringBootTest @AutoConfigureMockMvc(print=MockMvcPrint.NONE)
class ConversationIntegrationTest extends BusinessJwtTestSupport {
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired AiRequestBudget capacity;@Autowired AccountTokenStateService accounts;@Autowired JwtTokenService issuer;
 @MockitoBean AiChatClient python;
 Identity owner,other,admin;String merchant;UUID payment;JsonNode captured;Consumer<ObjectNode> corrupt;Runnable during;
 @BeforeEach void setup()throws Exception{merchant="chat-"+UUID.randomUUID();owner=identity("MERCHANT",Set.of(merchant));other=identity("MERCHANT",Set.of("chat-other-"+UUID.randomUUID()));admin=identity("ADMIN",Set.of());payment=payment(merchant,"INR","SUCCESS");captured=null;corrupt=r->{};during=()->{};when(python.chat(any())).thenAnswer(call->{assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());captured=((JsonNode)call.getArgument(0)).deepCopy();var security=org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();try{during.run();}finally{org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(security);}return reply(captured);});}
 UUID payment(String mid,String currency,String status){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO payments(payment_id,merchant_id,customer_id,amount,currency,payment_method,status) VALUES (?,?,'PRIVATE_CUSTOMER_MUST_NOT_LEAVE',100.00,?,'CARD',?)",id,mid,currency,status);return id;}
 ObjectNode reply(JsonNode req){var rules=ChatRules.expected(req);var r=json.createObjectNode();r.put("correlationId",req.path("correlationId").asText());r.set("evidenceCollectedAt",req.path("evidence").path("collectedAt"));r.put("answer",rules.answer());r.put("intent",rules.intent());r.set("evidenceReferences",json.valueToTree(rules.refs()));r.putArray("knowledgeReferences");r.set("limitations",json.valueToTree(rules.limitations()));r.set("suggestedFollowUps",ChatRules.CONTRACT.get("followUps"));r.set("moneyFacts",rules.money().deepCopy());r.put("analysisMode","DETERMINISTIC");r.put("generationStatus","DISABLED");corrupt.accept(r);return r;}
 MvcResult ask(Identity who,String path,Object body)throws Exception{return mvc.perform(post(path).with(jwt(who)).contentType("application/json").content(json.writeValueAsBytes(body))).andReturn();}
 JsonNode body(MvcResult r)throws Exception{return json.readTree(r.getResponse().getContentAsByteArray());}
 Map<String,Object> question(String q){return Map.of("question",q);}
 String payPath(){return "/api/v1/payments/"+payment+"/ai/chat";}
 String base="/api/v1/merchant/ai/conversations";
 String create(Identity who,String ns,Map<String,Object> extra)throws Exception{var b=new HashMap<String,Object>(extra);b.put("requestId",UUID.randomUUID().toString());var r=ask(who,ns,b);assertEquals(201,r.getResponse().getStatus(),r.getResponse().getContentAsString());return body(r).path("conversation").path("conversationId").asText();}
 String create()throws Exception{return create(owner,base,Map.of("context",Map.of("paymentId",payment.toString())));}
 MvcResult read(Identity who,String path)throws Exception{return mvc.perform(get(path).with(jwt(who))).andReturn();}
 Map<String,Object> sendBody(String rid,long version){return Map.of("requestId",rid,"expectedVersion",version,"question","What is this payment's recorded status?");}
 @Test void ownedImmutableScopeNoInference()throws Exception{String id=create();assertEquals(200,read(owner,base+"/"+id).getResponse().getStatus());assertEquals(404,read(other,base+"/"+id).getResponse().getStatus());assertEquals(403,read(admin,base+"/"+id).getResponse().getStatus());verifyNoInteractions(python);assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("UPDATE ai_conversations SET context='{}'::jsonb WHERE conversation_id=?::uuid",id));}
 @Test void privateAdminHistory()throws Exception{var a2=identity("ADMIN",Set.of());String id=create(admin,"/api/v1/admin/ai/conversations",Map.of());assertEquals(404,read(a2,"/api/v1/admin/ai/conversations/"+id).getResponse().getStatus());}
 @Test void creationReplayConflictDeletion()throws Exception{String rid=UUID.randomUUID().toString();var b=Map.of("requestId",rid);var first=ask(owner,base,b);assertEquals(201,first.getResponse().getStatus());String id=body(first).path("conversation").path("conversationId").asText();assertEquals(200,ask(owner,base,b).getResponse().getStatus());assertEquals(409,ask(owner,base,Map.of("requestId",rid,"title","Different title")).getResponse().getStatus());assertEquals(200,ask(owner,base+"/"+id+"/delete",Map.of("expectedVersion",0)).getResponse().getStatus());assertEquals(410,ask(owner,base,b).getResponse().getStatus());}
 @Test void completedReplayOneInference()throws Exception{String id=create(),rid=UUID.randomUUID().toString();var b=sendBody(rid,0);var r=ask(owner,base+"/"+id+"/messages",b);assertEquals(200,r.getResponse().getStatus(),r.getResponse().getContentAsString());assertEquals("COMPLETED",body(r).path("status").asText());assertEquals(200,ask(owner,base+"/"+id+"/messages",b).getResponse().getStatus());assertEquals(409,ask(owner,base+"/"+id+"/messages",Map.of("requestId",rid,"expectedVersion",0,"question","Different question")).getResponse().getStatus());verify(python,times(1)).chat(any());assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM ai_conversation_messages WHERE conversation_id=?::uuid",Integer.class,id));}
 @Test void serverHistoryBoundedFresh()throws Exception{String id=create();for(int i=0;i<6;i++){var r=ask(owner,base+"/"+id+"/messages",sendBody(UUID.randomUUID().toString(),i));assertEquals(200,r.getResponse().getStatus(),r.getResponse().getContentAsString());assertTrue(captured.path("history").size()<=8);}assertEquals(8,captured.path("history").size());jdbc.update("UPDATE payments SET status='FAILED' WHERE payment_id=?",payment);assertEquals(200,ask(owner,base+"/"+id+"/messages",sendBody(UUID.randomUUID().toString(),6)).getResponse().getStatus());assertEquals("FAILED",captured.path("evidence").path("payment").path("status").asText());}
 @Test void boundedListsAndMessages()throws Exception{for(int i=0;i<3;i++)create(owner,base,Map.of("title","Saved "+i));var list=read(owner,base+"?size=2&page=0&search=Saved");assertEquals(2,body(list).path("items").size());assertEquals(3,body(list).path("total").asInt());assertEquals(400,read(owner,base+"?size=11").getResponse().getStatus());String id=create();for(int i=0;i<3;i++)ask(owner,base+"/"+id+"/messages",sendBody(UUID.randomUUID().toString(),i));var page=body(read(owner,base+"/"+id+"/messages?page=0&size=2"));assertEquals(2,page.path("turns").get(0).path("turnIndex").asInt());assertEquals(3,page.path("turns").get(1).path("turnIndex").asInt());}
 @Test void strictRequests()throws Exception{for(String key:List.of("ownerId","role","history","evidence"))assertEquals(400,ask(owner,base,Map.of("requestId",UUID.randomUUID().toString(),key,"forged")).getResponse().getStatus());assertEquals(413,mvc.perform(post(base).with(jwt(owner)).contentType("application/json").content("x".repeat(8193))).andReturn().getResponse().getStatus());assertEquals(400,read(owner,base+"?page=0&page=1").getResponse().getStatus());assertEquals(400,ask(owner,base,Map.of("requestId",UUID.randomUUID().toString(),"context",Map.of("merchantId",merchant))).getResponse().getStatus());}
 @Test void renameVersionDeleteCascade()throws Exception{String id=create();assertEquals(200,ask(owner,base+"/"+id+"/rename",Map.of("title","Renamed","expectedVersion",0)).getResponse().getStatus());assertEquals(409,ask(owner,base+"/"+id+"/delete",Map.of("expectedVersion",0)).getResponse().getStatus());assertEquals(200,ask(owner,base+"/"+id+"/messages",sendBody(UUID.randomUUID().toString(),1)).getResponse().getStatus());assertEquals(200,ask(owner,base+"/"+id+"/delete",Map.of("expectedVersion",2)).getResponse().getStatus());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM ai_conversation_requests WHERE conversation_id=?::uuid",Integer.class,id));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM ai_conversation_messages WHERE conversation_id=?::uuid",Integer.class,id));}
 @Test void membershipRevocationHidesHistory()throws Exception{String id=create();jdbc.update("UPDATE merchant_memberships SET active=false WHERE user_id=?",owner.userId());assertTrue(Set.of(401,403,404).contains(read(owner,base+"/"+id+"/messages").getResponse().getStatus()));verifyNoInteractions(python);}
 @Test void invalidUpstreamNotStored()throws Exception{String id=create();corrupt=r->r.put("answer","Fabricated financial claim");assertEquals(502,ask(owner,base+"/"+id+"/messages",sendBody(UUID.randomUUID().toString(),0)).getResponse().getStatus());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM ai_conversation_messages WHERE conversation_id=?::uuid",Integer.class,id));}
 @Test void deleteDuringInference()throws Exception{String id=create();during=()->{try{assertEquals(200,ask(owner,base+"/"+id+"/delete",Map.of("expectedVersion",0)).getResponse().getStatus());}catch(Exception e){throw new RuntimeException(e);}};assertEquals(404,ask(owner,base+"/"+id+"/messages",sendBody(UUID.randomUUID().toString(),0)).getResponse().getStatus());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM ai_conversations WHERE conversation_id=?::uuid",Integer.class,id));}
 @Test void revocationDuringInference()throws Exception{String id=create();during=()->jdbc.update("UPDATE app_users SET authorization_version=authorization_version+1 WHERE user_id=?",owner.userId());assertEquals(401,ask(owner,base+"/"+id+"/messages",sendBody(UUID.randomUUID().toString(),0)).getResponse().getStatus());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM ai_conversation_messages WHERE conversation_id=?::uuid",Integer.class,id));}
 @Test void staleVersionDuringInference()throws Exception{String id=create();during=()->{try{ask(owner,base+"/"+id+"/rename",Map.of("title","New title","expectedVersion",0));}catch(Exception e){throw new RuntimeException(e);}};assertEquals(409,ask(owner,base+"/"+id+"/messages",sendBody(UUID.randomUUID().toString(),0)).getResponse().getStatus());}
 @Test void concurrentRequestsNoSecondInference()throws Exception{String id=create(),rid=UUID.randomUUID().toString();during=()->{try{assertEquals(202,ask(owner,base+"/"+id+"/messages",sendBody(rid,0)).getResponse().getStatus());assertEquals(409,ask(owner,base+"/"+id+"/messages",sendBody(UUID.randomUUID().toString(),0)).getResponse().getStatus());}catch(Exception e){throw new RuntimeException(e);}};assertEquals(200,ask(owner,base+"/"+id+"/messages",sendBody(rid,0)).getResponse().getStatus());verify(python,times(1)).chat(any());}
 @Test void financialAccountPreservation()throws Exception{String id=create();var before=jdbc.queryForList("SELECT row_to_json(p)::text FROM payments p ORDER BY payment_id");var a=jdbc.queryForList("SELECT row_to_json(a)::text FROM app_users a ORDER BY user_id");assertEquals(200,ask(owner,base+"/"+id+"/messages",sendBody(UUID.randomUUID().toString(),0)).getResponse().getStatus());assertEquals(before,jdbc.queryForList("SELECT row_to_json(p)::text FROM payments p ORDER BY payment_id"));assertEquals(a,jdbc.queryForList("SELECT row_to_json(a)::text FROM app_users a ORDER BY user_id"));}
 @Test void expiredContentUnavailable()throws Exception{String id=create();jdbc.update("UPDATE ai_conversations SET created_at=now()-interval '32 days',expires_at=now()-interval '1 day' WHERE conversation_id=?::uuid",id);assertEquals(404,read(owner,base+"/"+id).getResponse().getStatus());assertEquals(0,body(read(owner,base)).path("total").asInt());}
 @Test void atomicRollbackOnAssistantInsertFailure()throws Exception{String id=create();jdbc.execute("CREATE FUNCTION test_696_reject() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.message_role='assistant' THEN RAISE EXCEPTION 'test'; END IF; RETURN NEW; END $$");jdbc.execute("CREATE TRIGGER test_696_failure BEFORE INSERT ON ai_conversation_messages FOR EACH ROW EXECUTE FUNCTION test_696_reject()");try{assertEquals(503,ask(owner,base+"/"+id+"/messages",sendBody(UUID.randomUUID().toString(),0)).getResponse().getStatus());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM ai_conversation_messages WHERE conversation_id=?::uuid",Integer.class,id));}finally{jdbc.execute("DROP TRIGGER test_696_failure ON ai_conversation_messages");jdbc.execute("DROP FUNCTION test_696_reject()");}}

 @Autowired com.paymesh.backend.chat.conversations.ConversationTransactions transactions;
 @Autowired ConversationRetention retention;
 @Test void failedSameRequestMayRetryWithoutNewTurn()throws Exception{String id=create(),rid=UUID.randomUUID().toString();doThrow(new ChatFailure(504,"AI_TIMEOUT","Timeout")).when(python).chat(any());assertEquals(504,ask(owner,base+"/"+id+"/messages",sendBody(rid,0)).getResponse().getStatus());assertEquals("FAILED",body(read(owner,base+"/"+id+"/requests/"+rid)).path("status").asText());doAnswer(c->reply(c.getArgument(0))).when(python).chat(any());assertEquals(200,ask(owner,base+"/"+id+"/messages",sendBody(rid,0)).getResponse().getStatus());assertEquals(1,jdbc.queryForObject("SELECT turn_count FROM ai_conversations WHERE conversation_id=?::uuid",Integer.class,id));}
 @Test void crashedWorkerFencedByExplicitLeaseRetry()throws Exception{String id=create(),rid=UUID.randomUUID().toString();var input=new com.paymesh.backend.chat.conversations.ConversationDtos.Send(rid,0L,"What is this payment's recorded status?");var work=as(owner,()->transactions.begin("merchant",UUID.fromString(id),input));assertNull(work.immediate());assertEquals("IN_PROGRESS",body(read(owner,base+"/"+id+"/requests/"+rid)).path("status").asText());jdbc.update("UPDATE ai_conversation_requests SET lease_until=now()-interval '1 second' WHERE conversation_id=?::uuid",id);assertEquals("UNCERTAIN",body(read(owner,base+"/"+id+"/requests/"+rid)).path("status").asText());var next=as(owner,()->transactions.begin("merchant",UUID.fromString(id),input));assertNotEquals(work.nonce(),next.nonce());assertThrows(ChatFailure.class,()->as(owner,()->transactions.finish("merchant",work,null)));}
 @Test void differentRequestCannotBypassExpiredUnresolvedWork()throws Exception{String id=create();as(owner,()->transactions.begin("merchant",UUID.fromString(id),new com.paymesh.backend.chat.conversations.ConversationDtos.Send(UUID.randomUUID().toString(),0L,"Why?")));jdbc.update("UPDATE ai_conversation_requests SET lease_until=now()-interval '1 second' WHERE conversation_id=?::uuid",id);assertEquals(409,ask(owner,base+"/"+id+"/messages",sendBody(UUID.randomUUID().toString(),0)).getResponse().getStatus());verifyNoInteractions(python);}
 @Test void storageQuotaAndRetentionAreBounded()throws Exception{String id=create();jdbc.update("UPDATE ai_conversations SET turn_count=50 WHERE conversation_id=?::uuid",id);assertEquals(422,ask(owner,base+"/"+id+"/messages",sendBody(UUID.randomUUID().toString(),0)).getResponse().getStatus());jdbc.update("UPDATE ai_conversations SET created_at=now()-interval '32 days',expires_at=now()-interval '1 day' WHERE conversation_id=?::uuid",id);retention.sweep();assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM ai_conversations WHERE conversation_id=?::uuid",Integer.class,id));}
 @Test void strictVersionAndDuplicateJson()throws Exception{String id=create();for(String value:List.of("{\"expectedVersion\":\"0\",\"title\":\"Safe\"}","{\"expectedVersion\":0,\"expectedVersion\":1,\"title\":\"Safe\"}","{\"expectedVersion\":0.5,\"title\":\"Safe\"}"))assertEquals(400,mvc.perform(post(base+"/"+id+"/rename").with(jwt(owner)).contentType("application/json").content(value)).andReturn().getResponse().getStatus());}
 @Test void disabledAccountAndWrongPaymentContextsRejected()throws Exception{String id=create();assertEquals(404,ask(other,base,Map.of("requestId",UUID.randomUUID().toString(),"context",Map.of("paymentId",payment.toString()))).getResponse().getStatus());jdbc.update("UPDATE app_users SET enabled=false WHERE user_id=?",owner.userId());assertEquals(401,read(owner,base+"/"+id).getResponse().getStatus());verifyNoInteractions(python);}
 @Test void boundedJournalAndTurnDatabaseConstraints()throws Exception{String id=create();assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("UPDATE ai_conversations SET turn_count=51 WHERE conversation_id=?::uuid",id));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("UPDATE ai_conversations SET content_bytes=1048577 WHERE conversation_id=?::uuid",id));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("UPDATE ai_conversations SET title='' WHERE conversation_id=?::uuid",id));}
}
